<?php namespace App\Http\Controllers\Api; use App\Http\Resources\{CatechismClassResource,ChildResource}; use App\Models\CatechismClass; class ClassController extends ApiController { public function show(CatechismClass $class){$this->authorize('view',$class);$class->load(['academicYear','level','classroom','schedules','teachers.user'])->loadCount('children');return $this->success(new CatechismClassResource($class));} public function children(CatechismClass $class){$this->authorize('view',$class);$children=$class->children()->with(['parents.user'])->paginate(15);return $this->success(ChildResource::collection($children),'Fetched children',['current_page'=>$children->currentPage(),'last_page'=>$children->lastPage(),'per_page'=>$children->perPage(),'total'=>$children->total()]);} }
